queries.query:
BEGIN READ ONLY;
SELECT jsonb_build_object(
 'columns', (SELECT jsonb_agg(jsonb_build_object('table',table_name,'column',column_name,'type',data_type) ORDER BY table_name,ordinal_position) FROM information_schema.columns WHERE table_schema='public' AND (table_name IN ('__diag_maintenance_operation','__diag_maintenance_symptom_link','kg_nodes','kg_edges') OR table_name ILIKE '%maintenance%')),
 'constraints', (SELECT jsonb_agg(jsonb_build_object('table',conrelid::regclass::text,'name',conname,'definition',pg_get_constraintdef(oid))) FROM pg_constraint WHERE conrelid IN (SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace AND relname IN ('__diag_maintenance_operation','__diag_maintenance_symptom_link','kg_nodes','kg_edges')))
) AS evidence;
COMMIT;

BEGIN READ ONLY;
WITH intervals AS (SELECT * FROM public.kg_nodes WHERE node_type='MaintenanceInterval' AND is_active=true),
edges AS (SELECT e.* FROM public.kg_edges e WHERE e.is_active=true AND (e.source_node_id IN (SELECT node_id FROM intervals) OR e.target_node_id IN (SELECT node_id FROM intervals)))
SELECT jsonb_build_object(
'operations',(SELECT jsonb_agg(jsonb_build_object('id',id,'slug',slug,'system_id',system_id,'related_gamme_slug',related_gamme_slug,'related_pg_id',related_pg_id) ORDER BY id) FROM public.__diag_maintenance_operation WHERE active=true),
'intervals',(SELECT jsonb_agg(jsonb_build_object('node_id',node_id,'node_alias',node_alias,'label',node_label,'node_data',node_data,'sources',sources,'status',status,'km_interval',km_interval,'month_interval',month_interval) ORDER BY node_alias) FROM intervals),
'edges',(SELECT jsonb_agg(jsonb_build_object('source',source_node_id,'target',target_node_id,'type',edge_type,'evidence',evidence,'status',status) ORDER BY source_node_id,target_node_id) FROM edges),
'neighbors',(SELECT jsonb_agg(jsonb_build_object('node_id',n.node_id,'type',n.node_type,'alias',n.node_alias,'data',n.node_data) ORDER BY n.node_type,n.node_alias) FROM public.kg_nodes n WHERE n.node_id NOT IN (SELECT node_id FROM intervals) AND (n.node_id IN (SELECT source_node_id FROM edges) OR n.node_id IN (SELECT target_node_id FROM edges)))
) AS evidence;
COMMIT;
